package com.storemate.backend.web;
import com.storemate.backend.domain.*;import com.storemate.backend.repo.*;import org.junit.jupiter.api.*;import java.util.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class PushDispatchTest {
 PushDeliveryRepository deliveries=mock(PushDeliveryRepository.class);NotificationPreferenceRepository prefs=mock(NotificationPreferenceRepository.class);StoreMemberRepository members=mock(StoreMemberRepository.class);AuthTokenRepository tokens=mock(AuthTokenRepository.class);ExpoPushGateway gateway=mock(ExpoPushGateway.class);
 Account account=mock(Account.class);Store store=mock(Store.class);StoreMember member=mock(StoreMember.class);PushDevice device;Notification note;PushDelivery delivery;PushDispatcher dispatcher;
 @BeforeEach void setup()throws Exception{when(account.getId()).thenReturn(5L);when(store.getId()).thenReturn(3L);device=new PushDevice("ExpoPushToken[abcdefghijklmno]",account,"Asia/Seoul");device.bindSession("test-session");note=new Notification(store,Role.STAFF,1L,"task","업무","내용");var n=Notification.class.getDeclaredField("id");n.setAccessible(true);n.set(note,7L);delivery=new PushDelivery(note,device);var f=PushDelivery.class.getDeclaredField("id");f.setAccessible(true);f.set(delivery,9L);when(deliveries.findTop20ByStatusAndNextAttemptBeforeOrderByIdAsc(eq("PENDING"),any())).thenReturn(List.of(delivery));when(deliveries.lock(9L)).thenReturn(Optional.of(delivery));when(tokens.existsById("test-session")).thenReturn(true);when(members.findByAccountAndStore(account,store)).thenReturn(Optional.of(member));when(member.getStatus()).thenReturn(MemberStatus.APPROVED);when(member.getRole()).thenReturn(Role.STAFF);when(prefs.findByAccountId(5L)).thenReturn(Optional.empty());dispatcher=new PushDispatcher(deliveries,prefs,members,tokens,gateway,true);}
 @Test void acceptedTicketIsRecordedAndReceiptMarksDelivery(){when(gateway.send(device,note)).thenReturn(new ExpoPushGateway.Ticket("ticket-1",false));dispatcher.send();assertEquals("ACCEPTED",delivery.getStatus());when(deliveries.findTop20ByStatusAndNextAttemptBeforeOrderByIdAsc(eq("ACCEPTED"),any())).thenReturn(List.of(delivery));when(gateway.receipt("ticket-1")).thenReturn(ExpoPushGateway.Receipt.DELIVERED);dispatcher.receipts();assertEquals("DELIVERED",delivery.getStatus());}
 @Test void logoutOrPasswordResetPreventsSending(){when(tokens.existsById("test-session")).thenReturn(false);dispatcher.send();assertEquals("SKIPPED",delivery.getStatus());verifyNoInteractions(gateway);}
 @Test void rebindingDeviceCannotExposePreviousAccountsMessage(){var other=mock(Account.class);when(other.getId()).thenReturn(6L);device.update(other,"Asia/Seoul");dispatcher.send();assertEquals("SKIPPED",delivery.getStatus());verifyNoInteractions(gateway);}
 @Test void changingKindPreferenceAppliesToQueuedMessages(){var p=new NotificationPreference(account);p.update(true,false,true,true,true,true,false,"23:00","08:00");when(prefs.findByAccountId(5L)).thenReturn(Optional.of(p));dispatcher.send();assertEquals("SKIPPED",delivery.getStatus());verifyNoInteractions(gateway);}
 @Test void quietHoursDelayWithoutSending(){var p=new NotificationPreference(account);p.update(true,true,true,true,true,true,true,"00:00","00:00");when(prefs.findByAccountId(5L)).thenReturn(Optional.of(p));dispatcher.send();assertEquals("PENDING",delivery.getStatus());verifyNoInteractions(gateway);}
 @Test void invalidDeviceIsDisabled(){when(gateway.send(device,note)).thenReturn(new ExpoPushGateway.Ticket(null,true));dispatcher.send();assertFalse(device.isEnabled());assertEquals("SKIPPED",delivery.getStatus());}
 @Test void transientFailureIsRetryable(){when(gateway.send(device,note)).thenThrow(new IllegalStateException());dispatcher.send();assertEquals(1,delivery.getAttempts());assertEquals("PENDING",delivery.getStatus());}
}
